package jp.tapmarker;
import java.io.*;import java.util.*;import java.util.zip.*;

/** Held-out recording frames and chronological transitions through interrupted coin play. */
public final class Video6687ReplayTest {
 static final String P=CoinPreset.P;static int checks;static Map<String,float[]> refs;static final Map<String,VirtualPresetProfileTest.Image> images=new LinkedHashMap<>();
 static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static void load()throws Exception{refs=VirtualPresetProfileTest.canonical("tests/video6687-references.bin");try(DataInputStream in=new DataInputStream(new GZIPInputStream(new FileInputStream("tests/video6687-replay.bin.gz")))){int count=in.readInt(),nativeCount=0;for(int i=0;i<count;i++){String id=in.readUTF();VirtualPresetProfileTest.Image im=new VirtualPresetProfileTest.Image(in);images.put(id,im);if(im.width==856&&im.height==1920)nativeCount++;}check(count==62&&nativeCount==18&&in.read()==-1,"complete 6687 holdouts including native frames");}check(!images.containsKey("20")&&!images.containsKey("35")&&!images.containsKey("119")&&!images.containsKey("111.5"),"training timestamps are excluded from replay");}
 static final class Run {
  final PhaseEngine e=new PhaseEngine();final CoinLayout layout;final CoinMissionJourney journey=new CoinMissionJourney();Map<String,float[]> last;
  Run(){CoinPreset.install(e,refs);e.strictRuntime=true;layout=CoinLayout.install(e,refs);AdCloseAutomaton.install(e,CoinPreset.APP);check(layout!=null&&e.validate().isEmpty(),"valid complete factory graph");e.enter(P+"check",0);}
  Map<String,float[]> sample(String id,long now){VirtualPresetProfileTest.Image im=images.get(id);last=layout.sampleRelative(e.activeRegions(),im.width,im.height,im,now);return last;}
  PhaseEngine.Watch observe(String id,long now){e.observe(sample(id,now),now);return e.poll();}
  PhaseEngine.Watch pair(String a,String b,long now){PhaseEngine.Watch first=observe(a,now);check(first==null,"first observation holds action in "+e.current+" / "+a);return observe(b,now+350);}
  PhaseEngine.Watch advance(String a,String b,long now,String next,int action){PhaseEngine.Watch w=pair(a,b,now);check(w!=null&&w.action==action&&w.nextPhase.equals(P+next),"continuous "+e.current+" / "+a+" -> "+next+" / "+(w==null?e.diagnostic:w.id));if(action==PhaseEngine.CENTER){VirtualPresetProfileTest.Image im=images.get(b);check(e.confirmsAction(w,e.current,e.epoch,sample(b,now+400)),"fresh input confirms the same two landmarks");float[] point=layout.pointRelative(w,last,im.width,im.height);check(point!=null,"observed action supplies actual target coordinates");}e.finish(w,now+450);journey.completed(e,w,now+450);return w;}
 }
 static void tap2(){
  for(String state:new String[]{"main","check","verify","reward-ad"})for(String[] pair:new String[][]{{"25-native","30-native"},{"153-native","154-native"}}){Run r=new Run();r.e.enter(P+state,0);r.advance(pair[0],pair[1],1000,"boost-tap2",PhaseEngine.WAIT);check(!CoinPreset.playable(r.e,r.last),"tap2 modal holds marker loop");PhaseEngine.Watch w=r.advance(pair[0],pair[1],2000,"optional-cancel-wait",PhaseEngine.BACK);VirtualPresetProfileTest.Image im=images.get(pair[1]);float[] point=r.layout.pointRelative(w,r.last,im.width,im.height);check(point==null,"without cancel-letter evidence the fallback is Back, with no CM coordinates");}
  VirtualPresetProfileTest.Image im=images.get("30-native");for(int part=0;part<3;part++){Run r=new Run();r.e.enter(P+"boost-tap2",0);int[] cut=RegionMath.bounds(part==0?CoinPreset.TAP2_BODY:CoinPreset.TAP2_CM,im.width,im.height);final int kind=part;RegionSampler.Pixels absent=(x,y)->{int c=im.get(x,y);if(kind==2)return 0xff000000|((c>>16&255)/2)<<16|((c>>8&255)/2)<<8|(c&255)/2;return x>=cut[0]-2&&x<cut[2]+2&&y>=cut[1]-2&&y<cut[3]+2?0xff808080:c;};Map<String,float[]> s=r.layout.sampleRelative(r.e.activeRegions(),im.width,im.height,absent,1000);PhaseEngine.Watch w=r.e.rule(P+"boost-tap2-cm");check(!r.e.confirmsAction(w,r.e.current,r.e.epoch,s)&&r.layout.pointRelative(w,s,im.width,im.height)==null,"missing body, label or dimmed dialog cancels CM input");}
 }
 static void ads(){for(String id:new String[]{"35.5-native","120-native"}){Run r=new Run();r.e.enter(P+"reward-ad",0);PhaseEngine.Watch w=r.pair(id,id,1000);check(w!=null&&AdCloseAutomaton.handles(w.regionId)&&w.nextPhase.equals(P+"reward-ad"),"observed light ready glyph, preserving reward wait: "+id+" / "+r.e.diagnostic);VirtualPresetProfileTest.Image im=images.get(id);float[] p=r.layout.pointRelative(w,r.last,im.width,im.height);check(p!=null&&p[1]/im.height<.14f&&(id.startsWith("35")?p[0]/im.width>.87f:p[0]/im.width<.13f),"actual ready button stays inside the observed ad corner");Map<String,float[]> fresh=r.sample("155-native",1700);check(!r.e.confirmsAction(w,r.e.current,r.e.epoch,fresh)&&r.layout.pointRelative(w,fresh,im.width,im.height)==null,"loading screen invalidates prior ad-ready coordinates");}
  for(String id:new String[]{"36","113","115","155-native","165"}){Run r=new Run();r.e.enter(P+"reward-ad",0);PhaseEngine.Watch w=r.pair(id,id,1000);check(w==null,"browser/playing ad/loading/system frame has no guessed game or ad input: "+id);check(!CoinPreset.playable(r.e,r.last),"unknown/loading frame holds coin markers");}
 }
 static void chronological(){
  Run r=new Run();r.advance("5","10",1000,"main",PhaseEngine.WAIT);check(r.pair("90","95",2000)==null,"23/2 coins remaining and badge do not trigger mission inspection");
  r.advance("25-native","30-native",3000,"boost-tap2",PhaseEngine.WAIT);r.advance("25-native","30-native",4000,"optional-cancel-wait",PhaseEngine.BACK);r.e.enter(P+"verify",4500);r.advance("35.5-native","35.5-native",5000,"ad",PhaseEngine.CENTER);r.advance("40","45",6000,"main",PhaseEngine.WAIT);
  r.advance("95.5-native","96-native",7000,"clear",PhaseEngine.WAIT);check(CoinPreset.missionPending(r.e.current),"clear establishes mission intent before any ad");
  // The recorded bag disappears into an ad before a stable bonus frame.
  r.advance("99","100",8000,"mission-ad",PhaseEngine.CENTER);r.advance("99","100",9000,"mission-ad",PhaseEngine.CENTER);
  r.advance("103-native","104-native",10000,"mission-bonus",PhaseEngine.WAIT);r.advance("103-native","104-native",11000,"mission-opening",PhaseEngine.CENTER);
  r.advance("108","109",12000,"mission-tap",PhaseEngine.WAIT);PhaseEngine.Watch w=r.advance("110","111",13000,"mission-opening",PhaseEngine.CENTER);check(w.id.equals(P+"mission-button-tap"),"stage clear leads to the actual mission button once home is visible");
  r.advance("111.7-native","111.8-native",14000,"missions",PhaseEngine.WAIT);w=r.advance("111.7-native","111.8-native",15000,"claim-wait",PhaseEngine.CENTER);check(w.id.equals(P+"get-tap"),"unclaimed stage reward wins over Play");
  for(String state:new String[]{"clear","mission-ad","mission-opening","mission-bonus","claim-wait"})check(CoinPreset.recoveryTarget(P+state).equals(P+"mission-opening"),"external interruptions keep collection intent: "+state);
 }
 static void migrationAndTimers(){
  PhaseEngine old=CoinPreset.version170Defaults(refs),fresh=new PhaseEngine();CoinPreset.install(fresh,refs);check(old.phases.containsKey(P+"bonus-wait")&&!old.phases.containsKey(P+"boost-tap2"),"v170 factory shape remains recognizable");check(CoinPreset.upgrade(old,refs)&&AutomatonGraph.sameConfiguration(old,fresh)&&!CoinPreset.upgrade(old,refs),"v170 migration is complete and idempotent");old=CoinPreset.previousDefaults(refs);check(CoinPreset.upgrade(old,refs)&&AutomatonGraph.sameConfiguration(old,fresh),"v169 factory migration also matches final graph");check(!fresh.phases.containsKey(P+"bonus-wait")&&fresh.rule(P+"start-tap").nextPhase.equals(P+"verify"),"one classifier verifies all post-start branches");PhaseEngine empty=new PhaseEngine();check(!CoinPreset.upgrade(empty,refs)&&empty.phases.isEmpty(),"first-time loading installs the full graph instead of partial upgrade");
  Run r=new Run();r.e.enter(P+"clear",0);r.e.observe(Collections.emptyMap(),3000);PhaseEngine.Watch w=r.e.poll();check(w!=null&&w.nextPhase.equals(P+"mission-ad"),"clear timeout retains intent without authorizing any tap");r.e.finish(w,3000);check(!r.e.phases.get(r.e.current).markersDuring,"unknown post-clear pixels cannot resume coin input");
  old=CoinPreset.version170Defaults(refs);old.rule(P+"start-tap").action=PhaseEngine.BACK;check(!AutomatonGraph.sameConfiguration(old,CoinPreset.version170Defaults(refs)),"edited legacy action cannot be mistaken for untouched factory configuration");
 }
 static void journeyAndPreflight(){
  CoinMissionJourney journey=new CoinMissionJourney();check(journey.route(P+"bonus").equals(P+"bonus")&&!journey.blocksMain(),"ordinary bonus alone does not request mission inspection");
  journey.route(P+"clear");for(String state:new String[]{"check","ad","boost-tap2","reward-ad","external","verify"})check(journey.route(P+state).equals(P+state)&&journey.blocksMain(),"clear intent survives classifier and boost interruption: "+state);
  check(journey.route(P+"bonus").equals(P+"mission-bonus")&&journey.route(P+"main").equals(P+"mission-tap"),"pending collection routes confirmed bonus/home back to missions");
  PhaseEngine e=new PhaseEngine();CoinPreset.install(e,refs);e.current=P+"mission-verify";journey.completed(e,e.rule(P+"mission-play"),1000);check(!journey.blocksMain()&&journey.route(P+"main").equals(P+"main"),"successful Play input releases collection while its verify state still holds markers");
  Run r=new Run();r.e.enter(P+"missions",0);PhaseEngine.Watch get=r.pair("111.7-native","111.8-native",1000);check(get!=null&&get.id.equals(P+"get-tap"),"uncovered Get letters beat anchor wait despite obscured old orange probe");
  VirtualPresetProfileTest.Image im=images.get("111.8-native");Map<String,float[]> fresh=r.sample("111.8-native",1500);check(r.e.confirmsAction(get,r.e.current,r.e.epoch,fresh),"fresh Get preflight confirms heading and visible white text");float[] point=r.layout.pointRelative(get,fresh,im.width,im.height);check(point!=null&&point[0]>625&&point[0]<760&&point[1]>750&&point[1]<817,"Get point is visible inside button, outside overlay");
  for(String id:new String[]{"112-native","112.1-native","113","155-native"}){fresh=r.sample(id,2000);check(!r.e.confirmsAction(get,r.e.current,r.e.epoch,fresh)&&r.layout.pointRelative(get,fresh,im.width,im.height)==null,"pressed/dim/ad/loading frames cancel pending Get: "+id);}
  r=new Run();r.e.enter(P+"reward-ad",0);check(r.pair("155-native","155-native",1000)==null,"actual dim loading frame cannot resume coin dropping");r.advance("156","157-native",2000,"main",PhaseEngine.WAIT);check(CoinPreset.playable(r.e,r.last),"actual bright returned home resumes only after two observations");
 }
 static void geometry(){VirtualPresetProfileTest.Image im=images.get("154-native");for(float[] t:new float[][]{{1,1,0,0},{1,.90f,0,.06f},{.94f,.86f,.03f,.08f}}){Run r=new Run();r.e.enter(P+"boost-tap2",0);int width=720,height=1616;RegionSampler.Pixels p=(x,y)->{float nx=(x/(float)width-t[2])/t[0],ny=(y/(float)height-t[3])/t[1];return nx<0||nx>=1||ny<0||ny>=1?0xff142030:im.get(Math.min(im.width-1,(int)(nx*im.width)),Math.min(im.height-1,(int)(ny*im.height)));};Map<String,float[]> s=r.layout.sampleRelative(r.e.activeRegions(),width,height,p,1000);PhaseEngine.Watch w=r.e.rule(P+"boost-tap2-cm");float[] point=r.layout.pointRelative(w,s,width,height),expected=AdaptiveLayout.map(CoinPreset.TAP2_CM,t);check(r.e.confirmsAction(w,r.e.current,r.e.epoch,s)&&w.action==PhaseEngine.BACK&&point==null,"resized/inset modal is recognized without authorizing a CM input");check(r.layout.pointRelative(w,s,width+1,height)==null,"changed frame size invalidates tap2 point");}
 }
 public static void main(String[] args)throws Exception{load();tap2();ads();chronological();migrationAndTimers();journeyAndPreflight();geometry();System.out.println("Video6687ReplayTest: "+checks+" checks passed; held-out tap2/ad-ready, chronological clear/ad/start/mission/Get, migrations, negative and relative-input checks; device input and extra game UIs untested");}
}
